      on_fail("http:adapter-error")
      return
    end
    if self._done then
      if cancel then
        pcall(cancel)
      end
    else
      self._http_cancel = cancel
    end
  end

  function self._open_websocket(hub, token, on_ok, on_fail)
    local ws_path = hub.path .. "?id=" .. pct_encode(token)
    local key = self._client_key()
    local expected = WS.expected_accept(key, self._sha1, self._b64encode)
    local handshake_done = false
    local cancel_upgrade = self._after(30000, function()
      on_fail("timeout:upgrade")
    end)
    self._dispatcher.on_handshake = function()
      cancel_upgrade()
      on_ok()
    end
    local handshake_buffer = ""
    local parser = WS.new_parser({
      on_message = function(payload, is_binary)
        if is_binary then
          -- The Home Assistant reader skips non-text messages; do the same.
          self._log_debug("ignoring binary websocket frame")
          return
        end
        self._dispatcher.feed(payload)
      end,
      send_frame = function(payload, opcode)
        if self._tcp ~= nil then
          self._tcp.send(WS.build_client_frame(payload, self._random_mask(), opcode))
        end
      end,
      on_close = function(code, _reason)
        if not self._done then
          on_fail("ws:closed-" .. tostring(code))
        end
      end,
      on_error = function(msg)
        if not self._done then
          on_fail("ws:" .. tostring(msg))
        end
      end,
    })
    self._ws_parser = parser
    -- The transport may report on_open synchronously (before tcp_open
    -- returns), so the handshake send is deferred until self._tcp exists.
    local opened, handshake_sent = false, false
    local function send_handshake()
      if handshake_sent or self._done or self._tcp == nil then
        return
      end
      handshake_sent = true
      local headers = {}
      for name, value in pairs(self._connection_headers) do
        if type(value) ~= "string" or value:find("[\r\n]") then
          on_fail("ws:invalid-connection-header")
          return
        end
        headers[#headers + 1] = name .. ": " .. value
      end
      local request = WS.build_handshake_request(hub.host .. ":" .. tostring(hub.port), ws_path, key, headers)
      if not pcall(self._tcp.send, request) then
        on_fail("ws:send-failed")
      end
    end
    local ok_open, tcp, tcp_err = pcall(self._tcp_open, hub.host, hub.port, {
      on_open = function()
        opened = true
        send_handshake()
      end,
      on_data = function(bytes)
        if self._done then
          return
        end
        if not handshake_done then
          handshake_buffer = handshake_buffer .. bytes
          local accept, consumed_or_err = WS.parse_handshake_response(handshake_buffer)
          if accept == nil and consumed_or_err == "need_more" then
            return
          end
          if accept == nil then
            on_fail("ws:" .. tostring(consumed_or_err))
            return
          end
          if accept ~= expected then
            on_fail("ws:bad-accept-key")
            return
          end
          handshake_done = true
          local rest = handshake_buffer:sub(consumed_or_err + 1)
          handshake_buffer = ""
          if not self._send_text(SignalR.handshake_message()) then
            on_fail("ws:send-failed")
            return
          end
          if rest ~= "" then
            parser.feed(rest)
          end
        else
          parser.feed(bytes)
        end
      end,
      on_close = function()
        if not self._done then
          on_fail("ws:tcp-closed")
        end
      end,
      on_error = function(msg)
        if not self._done then
          on_fail("ws:" .. tostring(msg))
        end
      end,
    })
    if not ok_open then
      on_fail("ws:adapter-error")
      return
    end
    if tcp == nil then
      on_fail("ws:" .. tostring(tcp_err or "tcp-open-failed"))
      return
    end
    if self._done then
      tcp.close()
      return
    end
    self._tcp = tcp
    if opened then
      send_handshake()
    end
  end

  function self._login(on_ok, on_fail)
    self._log_debug("login")
    self._wait_for("LoggedIn", 30000, function(args)
      local user = args[1]
      if type(user) ~= "table" or user.id == nil then
        on_fail("auth")
        return
      end
      self._user = user
      if type(user.relogToken) == "string" and user.relogToken ~= "" then
        self._relog_token = user.relogToken
        self.relog_token = user.relogToken
      end
      self._refresh_valve_array(user, function(devices)
        self._devices = devices
        on_ok(user, devices)
      end, on_fail)
    end, on_fail)
    if not self._invoke("Login", { self._email, self._password, self._device_name, JSON.null }) then
      on_fail("ws:send-failed")
    end
  end

  function self._refresh_valve_array(user, on_ok, on_fail)
    self._wait_for("ValveArraySent", 30000, function(args)
      local clean = validate_inventory(args[1])
      if not clean then
        on_fail("bad-valve-array")
        return
      end
      on_ok(clean)
    end, on_fail)
    if not self._invoke("RefreshValveArray", { user }) then
      on_fail("ws:send-failed")
    end
  end

  function self._connect(hub_url, on_ready, on_fail)
    self._after(180000, function()
      on_fail("timeout:session")
    end)
    local hub, hub_err = FloLogic.parse_hub_url(hub_url)
    if hub == nil then
      on_fail(hub_err)
      return
    end
    self._dispatcher = SignalR.new_dispatcher({
      on_event = function(target, args)
        if self._trace_events then
          self._log_warn("hub event: " .. tostring(target))
        end
        if target == "ErrorOccured" then
          -- The Home Assistant client logs this and continues; a cloud
          -- error notice must not abort a fetch that is otherwise healthy.
          self._log("cloud ErrorOccured event ignored")
        elseif target == "ValveArraySent" and self._devices then
          local devices = validate_inventory(args[1])
          if not devices then
            on_fail("bad-valve-array")
            return
          end
          self._devices = devices
          if self._confirm_check ~= nil then
            self._confirm_check()
          end
        elseif target == "ValveSent" and type(args[1]) == "table" and self._devices then
          -- Merge, mirroring the Home Assistant cache: replace the matching
          -- valve, or add a pushed valve the array has not listed yet.
          local incoming = args[1]
          if incoming.id ~= nil then
            local merged = false
            for index, valve in ipairs(self._devices) do
              if tostring(valve.id) == tostring(incoming.id) then
                self._devices[index] = incoming
                merged = true
                break
              end
            end
            if not merged then
              self._devices[#self._devices + 1] = incoming
            end
            if self._confirm_check ~= nil then
              self._confirm_check()
            end
          end
        end
      end,
      on_error = function(msg, detail)
        -- The Home Assistant client ignores undecodable and malformed
        -- frames; only transport-level failures abort the session.
        if msg == "undecodable SignalR frame" or msg == "bad-event" then
          if self._trace_events and detail ~= nil then
            self._log_warn("undecodable hub frame: " .. tostring(detail))
          else
            self._log_debug("ignoring " .. msg)
          end
          return
        end
        on_fail("signalr:" .. msg)
      end,
    })
    self._negotiate(hub, function(token)
      self._open_websocket(hub, token, function()
        self._login(function(user, devices)
          on_ready(user, devices)
        end, on_fail)
      end, on_fail)
    end, on_fail)
  end

  --- Resolve an explicit selection against the authoritative controllable inventory.
  function self._ensure_valve(user, devices, selected, on_ok, on_fail)
    local valves = FloModel.controllable_valves(devices)
    local valve = selected and selected ~= "" and FloModel.find_valve(valves, selected)
    if not valve then
      on_fail(selected and selected ~= "" and "valve-not-found" or "select-valve")
      return
    end
    on_ok(valve, devices, valves)
  end

  function self._fetch_access(user, valve, on_ok, on_fail)
    self._wait_for("UserAccessesSent", 30000, function(args)
      local accesses = args[1]
      local access = nil
      if type(accesses) == "table" then
        for _, row in ipairs(accesses) do
          if type(row) == "table" and row.valveId == valve.id then
            access = row
            break
          end
        end
      end
      on_ok(access)
    end, function(_timeout_err)
      on_ok(nil) -- access is optional; timeouts degrade like scheduler/notifications
    end)
    if not self._invoke("RequestUserAccesses", { user }) then
      on_fail("ws:send-failed")
    end
  end

  function self._fetch_scheduler(user, valve, on_ok, on_fail)
    self._wait_for("SchedulerEventsSent", 30000, function(args)
      local rows = args[1]
      if type(rows) ~= "table" then
        rows = {}
      end
      on_ok(rows)
    end, function(_timeout_err)
      on_ok({}) -- scheduler is optional; timeouts degrade to empty
    end)
    if not self._invoke("RequestSchedulerEvents", { user.id, valve.id }) then
      on_fail("ws:send-failed")
    end
  end

  function self._fetch_notifications(user, valve, on_ok, on_fail)
    -- Per-valve history only. There is deliberately no account-wide retry:
    -- an empty history must never pull in another site's notifications.
    self._wait_for("NotificationsHistorySent", 30000, function(args)
      local rows = args[1]
      if type(rows) == "table" then
        on_ok(rows)
      else
        on_ok({})
      end
    end, function(_timeout_err)
      on_ok({})
    end)
    if not self._invoke("RefreshValvesNotificationsHistory", { user.id, { valve.id } }) then
      on_fail("ws:send-failed")
    end
  end

  -- Fetch one poll snapshot for the selected valve. selected may be a valve
  -- ID or UUID. A blank selection discovers inventory only.
  -- cb(err, snapshot) with snapshot = { user, devices, valves, valve,
  -- access, scheduler, notifications }.
  function self.fetch_snapshot(hub_url, selected, cb)
    local function fail(err)
      self._finish(err, nil, cb)
    end
    self._connect(hub_url, function(user, devices)
      if selected == nil or selected == "" then
        self._finish(nil, { user = user, devices = devices }, cb)
        return
      end
      self._ensure_valve(user, devices, selected, function(valve)
        self._fetch_access(user, valve, function(access)
          self._fetch_scheduler(user, valve, function(scheduler)
            self._fetch_notifications(user, valve, function(notifications)
              local valves = FloModel.controllable_valves(self._devices)
              local latest = FloModel.find_valve(valves, valve.id)
              if not latest then
                fail("valve-not-found")
                return
              end
              self._finish(nil, {
                user = user,
                devices = self._devices,
                valves = valves,
                valve = latest,
                access = access,
                scheduler = scheduler,
                notifications = notifications,
              }, cb)
            end, fail)
          end, fail)
        end, fail)
      end, fail)
    end, fail)
  end

  -- Send one state-change command. fields is a flat table of cloud values.
  -- The hub applies RequestStateChange immediately, but the
  -- StateChangeResult event is unreliable: slow or offline valves may
  -- produce it late or never, while the cloud-side state already changed.
  -- So the event is only the fast path: inventory verification races it,
  -- and any post-invoke row showing the requested fields counts as
  -- success. Failure needs BOTH the event timeout AND no confirmation.
  function self.send_command(hub_url, selected, fields, cb)
    local function fail(err)
      self._finish(err, nil, cb)
    end
    if selected == nil or selected == "" then
      fail("select-valve")
      return
    end
    self._trace_events = true
    self._connect(hub_url, function(user, devices)
      self._ensure_valve(user, devices, selected, function(valve)
        local command = {
          active = true,
          created = os.date("!%Y-%m-%dT%H:%M:%SZ"),
          userId = user.id,
          valveId = valve.id,
        }
        for k, v in pairs(fields) do
          if command[k] ~= nil then
            fail("reserved-command-field")
            return
          end
          command[k] = v
        end
        local function row_matches(row)
          if type(row) ~= "table" then
            return false
          end
          for key, want in pairs(fields) do
            if key == "mode" then
              -- Inventory mode is a flag combo; the requested bit set is
              -- what counts (mirrors the mode-name flag fallbacks).
              local have = tonumber(row.mode)
              local want_num = tonumber(want)
              if have == nil or want_num == nil or not FloModel.has_flag(have, want_num) then
                return false
              end
            else
              local have_num, want_num = tonumber(row[key]), tonumber(want)
              if have_num ~= nil and want_num ~= nil then
                if have_num ~= want_num then
                  return false
                end
              elseif row[key] ~= want then
                return false
              end
            end
          end
          return true
        end
        local function find_row()
          if type(self._devices) ~= "table" then
            return nil
          end
          for _, row in ipairs(self._devices) do
            if type(row) == "table" then
              if tostring(row.id) == tostring(valve.id) then
                return row
              end
              if valve.uuid ~= nil and row.uuid == valve.uuid then
                return row
              end
            end
          end
          return nil
        end
        local function try_confirm(source)
          if self._done then
            return
          end
          local row = find_row()
          if row ~= nil and row_matches(row) then
            self._log_warn("command confirmed by " .. source)
            self._finish(nil, { valve = row }, cb)
          end
        end
        -- Push fast path: _connect merges ValveArraySent/ValveSent rows and
        -- runs this hook after every merge.
        self._confirm_check = function()
          try_confirm("push")
        end
        -- Scheduled explicit verifies for the no-push case. Verify errors
        -- never fail the command; the event timeout still owns failure.
        for _, delay_ms in ipairs({ 10000, 22000, 34000 }) do
          self._after(delay_ms, function()
            if self._done then
              return
            end
            try_confirm("cache")
            if self._done then
              return
            end
            self._log_warn("command verify refresh (no confirmation yet)")
            -- The merge hook above confirms from this reply; the waiter
            -- only needs to consume it.
            self._refresh_valve_array(user, function(refreshed)
              self._devices = refreshed
            end, function() end)
          end)
        end
        self._wait_for("StateChangeResult", 45000, function(args)
          local result = args[1]
          if result == false or (type(result) == "table" and (result.ok == false or result.success == false)) then
            fail("command-rejected")
            return
          end
          self._finish(nil, { valve = valve }, cb)
        end, function(err)
          self._finish(err, nil, cb)
        end)
        self._log_warn("invoke RequestStateChange")
        if not self._invoke("RequestStateChange", { user, valve, command }) then
          self._finish("ws:send-failed", nil, cb)
        else
          -- Idempotent fast path: the just-fetched inventory may already
          -- show the requested state (the invoke above still flew, so hub
          -- side effects are preserved).
          try_confirm("cache")
        end
      end, fail)
    end, fail)
  end

  return self
end

-- ============================================================================
-- bundled: src/update.lua
-- ============================================================================
-- GitHub release discovery. Installation remains a Composer operation.
FloUpdate = {}
FloUpdate.REPOSITORY = "psaab/flologic_HA"
FloUpdate.ASSET = "flologic_valve.c4z"
FloUpdate.API_URL = "https://api.github.com/repos/" .. FloUpdate.REPOSITORY .. "/releases?per_page=100"

--- Ignore HA releases, drafts, prereleases, and releases without the C4 asset.
function FloUpdate.select_release(releases)
  if type(releases) ~= "table" or releases.message ~= nil then
    return nil, "Invalid GitHub release response"
  end
  local best
  for _, release in ipairs(releases) do
    if type(release) == "table" and not release.draft and not release.prerelease then
      local tag = release.tag_name
      local version = type(tag) == "string" and tag:match("^c4%-v(%d%d%d%d%d%d%d%d%d%d)$")
      if version and type(release.assets) == "table" then
        local expected = "https://github.com/"
          .. FloUpdate.REPOSITORY
          .. "/releases/download/"
          .. tag
          .. "/"
          .. FloUpdate.ASSET
        for _, asset in ipairs(release.assets) do
          if type(asset) == "table" and asset.name == FloUpdate.ASSET and asset.browser_download_url == expected then
            if not best or version > best.version then
              best = { version = version, url = expected }
            end
          end
        end
      end
    end
  end
  return best
end

--- A cancellable, report-only check; callbacks never run after cancel/reload.
function FloUpdate.new_check(opts)
  local self = { done = false }
  function self.cancel()
    self.done = true
    if self.cancel_timer then
      pcall(self.cancel_timer)
      self.cancel_timer = nil
    end
    if self.cancel_http then
      pcall(self.cancel_http)
      self.cancel_http = nil
    end
  end
  local function finish(err, release)
    if self.done then
      return
    end
    self.cancel()
    opts.on_result(err, release)
  end
  function self.start()
    if self.done or self.started then
      return
    end
    self.started = true
    self.cancel_timer = opts.set_timeout(35000, function()
      finish("GitHub request timed out")
    end)
    local ok, cancel = pcall(opts.http_get, FloUpdate.API_URL, {
      Accept = "application/vnd.github+json",
      ["User-Agent"] = "FloLogic-Control4",
      ["X-GitHub-Api-Version"] = "2022-11-28",
    }, function(err, body, code)
      if self.done then
        return
      end
      if err then
        finish("GitHub request failed")
        return
      end
      if code == 403 or code == 429 then
        finish("GitHub rate limited or denied the request; try later")
        return
      end
      if code ~= 200 then
        finish("GitHub HTTP " .. tostring(code))
        return
      end
      if type(body) ~= "string" or #body > 1048576 then
        finish("Invalid GitHub response size")
        return
      end
      local decoded, releases = pcall(JSON.decode, body)
      if not decoded then
        finish("Invalid GitHub JSON")
        return
      end
      local release, reason = FloUpdate.select_release(releases)
      finish(reason, release)
    end)
    if not ok then
      finish("GitHub transport unavailable")
      return
    end
    if self.done then
      if cancel then
        pcall(cancel)
      end
    else
      self.cancel_http = cancel
    end
  end
  return self
end

FloUpdate.C4Z_ROOT = "C4Z_ROOT"
FloUpdate.SOAP_HOST = "127.0.0.1"
FloUpdate.SOAP_PORT = 5020
FloUpdate.MAX_REDIRECTS = 5
FloUpdate.MAX_PACKAGE_BYTES = 8 * 1024 * 1024

--- Compare driver versions ("YYYYMMDDNN" date-numbers): -1, 0, or 1.
--- Falls back to lexicographic order for anything else.
function FloUpdate.compare_versions(a, b)
  local sa, sb = tostring(a or ""), tostring(b or "")
  if sa == sb then
    return 0
  end
  if sa:match("^%d+$") and sb:match("^%d+$") then
    if #sa ~= #sb then
      return #sa < #sb and -1 or 1
    end
    return sa < sb and -1 or 1
  end
  return sa < sb and -1 or 1
end

local function flo_update_xml_escape(value)
  return tostring(value or "")
    :gsub("&", "&amp;")
    :gsub("<", "&lt;")
    :gsub(">", "&gt;")
    :gsub('"', "&quot;")
    :gsub("'", "&apos;")
end

--- Exact c4soap packet Composer's local endpoint installs by name.
--- NUL-terminated per the local protocol.
function FloUpdate.build_install_packet(filename)
  return '<c4soap async="0" category="composer" name="UpdateProjectC4i"'
    .. ' operation="RWX" session="0">'
    .. '<param name="name" type="string">'
    .. flo_update_xml_escape(filename)
    .. "</param></c4soap>\000"
end

--- A cancellable install operation; callbacks never run after cancel/reload.
--- Downloads the latest C4 asset, stages it in the C4Z file store (verified
--- by on-disk size plus a zip-magic read-back), and triggers Composer to
--- install it by name. force skips the version compare, so it can reinstall
--- the same build or even an older one; that is the intended recovery
--- semantic.
--- opts.http_get(url, headers, cb) has cb(err, body, code, headers_or_nil)
--- and returns a cancel function. opts.soap_send(packet, cb(err)) likewise.
--- File callbacks: get_installed() -> bool, file_set_dir(alias) -> ok,
--- file_exists(name) -> bool, file_delete(name), file_write(name, data),
--- file_size(name) -> bytes or nil, file_read(name, count) -> string or nil.
--- File callbacks must not throw; the Director adapter wraps every C4 file
--- call in pcall and converts denials to false/nil. opts.log_warn(msg)
--- traces download/stage/trigger milestones to the Lua log (default noop).
--- on_result(err, outcome) has outcome
--- { attempted = version|nil, latest = version|nil, skipped = reason|nil }.
function FloUpdate.new_install(opts)
  local self = { done = false }
  local log_warn = opts.log_warn or function() end
  function self.cancel()
    self.done = true
    if self.cancel_timer then
      pcall(self.cancel_timer)
      self.cancel_timer = nil
    end
    if self.cancel_http then
      pcall(self.cancel_http)
      self.cancel_http = nil
    end
    if self.cancel_soap then
      pcall(self.cancel_soap)
      self.cancel_soap = nil
    end
  end
  local function finish(err, outcome)
    if self.done then
      return
    end
    self.cancel()
    opts.on_result(err, outcome)
  end
  local function progress(text)
    if not self.done and opts.on_progress then
      opts.on_progress(text)
    end
  end
  local function arm(ms, message)
    if self.cancel_timer then
      pcall(self.cancel_timer)
      self.cancel_timer = nil
    end
    self.cancel_timer = opts.set_timeout(ms, function()
      finish(message)
    end)
  end
  local function track_http(cancel)
    if self.done then
      if cancel then
        pcall(cancel)
      end
    else
      self.cancel_http = cancel
    end
  end
  local function get_releases(cb)
    arm(35000, "GitHub request timed out")
    local ok, cancel = pcall(opts.http_get, FloUpdate.API_URL, {
      Accept = "application/vnd.github+json",
      ["User-Agent"] = "FloLogic-Control4",
      ["X-GitHub-Api-Version"] = "2022-11-28",
    }, function(err, body, code)
      if self.done then
        return
      end
      self.cancel_http = nil
      if err then
        finish("GitHub request failed")
        return
      end
      if code == 403 or code == 429 then
        finish("GitHub rate limited or denied the request; try later")
        return
      end
      if code ~= 200 then
        finish("GitHub HTTP " .. tostring(code))
        return
      end
      if type(body) ~= "string" or #body > 1048576 then
        finish("Invalid GitHub response size")
        return
      end
      local decoded, releases = pcall(JSON.decode, body)
      if not decoded then
        finish("Invalid GitHub JSON")
        return
      end
      local release, reason = FloUpdate.select_release(releases)
      if not release then
        finish(reason or "No published C4 package found in recent releases")
        return
      end
      cb(release)
    end)
    if not ok then
      finish("GitHub transport unavailable")
      return
    end
    track_http(cancel)
  end
  local function download(url, redirects_left, cb)
    arm(120000, "Download timed out")
    local ok, cancel = pcall(opts.http_get, url, {}, function(err, body, code, headers)
      if self.done then
        return
      end
      self.cancel_http = nil
      if err then
        finish("Download failed")
        return
      end
      if code == 301 or code == 302 or code == 307 or code == 308 then
        local location = nil
        if type(headers) == "table" then
          for name, value in pairs(headers) do
            if tostring(name):lower() == "location" and value ~= "" then
              location = value
              break
            end
          end
        end
        if location == nil then
          finish("Asset redirect not followed by transport")
          return
        end
        if redirects_left <= 0 then
          finish("Too many download redirects")
          return
        end
        download(location, redirects_left - 1, cb)
        return
      end
      if code ~= 200 then
        finish("Download HTTP " .. tostring(code))
        return
      end
      if type(body) ~= "string" or #body < 1 then
        finish("Downloaded package is empty")
        return
      end
      if #body > FloUpdate.MAX_PACKAGE_BYTES then
        finish("Downloaded package is too large")
        return
      end
      log_warn("update download: " .. #body .. " bytes, HTTP " .. tostring(code))
      cb(body)
    end)
    if not ok then
      finish("Download transport unavailable")
      return
    end
    track_http(cancel)
  end
  local function stage(filename, body, cb)
    arm(30000, "Install staging timed out")
    -- Switch stores BEFORE deleting anything: on denial the installed file
    -- stays intact and no install is triggered. Falling through would write
    -- and verify against the wrong directory, then reinstall the unchanged
    -- old build as a silent no-op.
    progress("Staging " .. filename .. " (" .. #body .. " bytes)")
    local switched = opts.file_set_dir(FloUpdate.C4Z_ROOT)
    if not switched then
      finish("File store " .. FloUpdate.C4Z_ROOT .. " denied; installed driver left intact")
      return
    end
    if opts.file_exists(filename) then
      opts.file_delete(filename)
    end
    opts.file_write(filename, body)
    -- Never trust the write call: verify by on-disk SIZE (a number), not by
    -- re-reading the full binary that can false-mismatch through string
    -- marshalling. A 4-byte magic read-back additionally proves the staged
    -- file is a driver archive rather than an error page or truncation.
    if opts.file_size(filename) ~= #body then
      finish("Staged package size mismatch; stored package may be missing or incomplete; restore using Composer")
      return
    end
    if opts.file_read(filename, 4) ~= "PK\003\004" then
      log_warn("update stage: magic check failed for " .. filename)
      finish(
        "Staged package is not a driver archive; stored package may be missing or incomplete; restore using Composer"
      )
      return
    end
    log_warn("update stage: " .. filename .. " verified (" .. #body .. " bytes, zip magic ok)")
    cb()
  end
  function self.start()
    if self.done or self.started then
      return
    end
    self.started = true
    if not opts.get_installed() then
      finish(nil, { skipped = "not-installed" })
      return
    end
    get_releases(function(release)
      if not opts.force and FloUpdate.compare_versions(release.version, opts.current_version) <= 0 then
        finish(nil, { attempted = nil, latest = release.version, skipped = "up-to-date" })
        return
      end
      progress("Downloading " .. release.version)
      download(release.url, FloUpdate.MAX_REDIRECTS, function(body)
        stage(FloUpdate.ASSET, body, function()
          progress("Installing " .. release.version)
          arm(30000, "Install trigger timed out")
          log_warn("update trigger: UpdateProjectC4i " .. FloUpdate.ASSET)
          local ok, cancel = pcall(opts.soap_send, FloUpdate.build_install_packet(FloUpdate.ASSET), function(err)
            if self.done then
              return
            end
            self.cancel_soap = nil
            if err then
              log_warn("update trigger failed: " .. tostring(err))
              finish("Install trigger failed: " .. tostring(err))
              return
            end
            log_warn("update trigger sent for " .. release.version)
            finish(nil, { attempted = release.version, latest = release.version })
          end)
          if not ok then
            finish("Install trigger unavailable")
            return
          end
          if self.done then
            if cancel then
              pcall(cancel)
            end
          else
            self.cancel_soap = cancel
          end
        end)
      end)
    end)
  end
  return self
end

